  useEffect(() => {
    setCoreWheel(null);
    setAccessoryWheel(null);
    setPendingCoreWheelLog(null);
    setPendingAccessoryLogItemId(null);
    setSupersetRoundLogger(null);
    setNavigatorVisible(false);
