  const updateFcInput = (
    key: string,
    field: 'weight' | 'reps' | 'rpe',
    value: string,
  ) => {
    let v = value ?? '';

    if (field === 'reps') {
      v = v.replace(/[^0-9]/g, '');
    } else {
      v = v.replace(/[^0-9.]/g, '');
      const d = v.indexOf('.');
      if (d !== -1) v = v.slice(0, d + 1) + v.slice(d + 1).replace(/\./g, '');
    }

    setFcInputs((prev) => ({
      ...prev,
      [key]: {
        weight: prev[key]?.weight || '',
        reps: prev[key]?.reps || '',
        rpe: prev[key]?.rpe || '',
        [field]: v,
      },
    }));
  };

