  const chooseReadinessAndBegin = async (choice: 'submit' | 'skip') => {
    const gate = readinessStartGateRef.current;
    const intent = gate.current();
    if (!intent || gate.isWorking() || intent.preview || intent.scope !== executionScopeRef.current || !canLogFromServer) return;
    if (choice === 'submit' && (!readinessCanSubmit || readinessChecking)) return;
    const built = choice === 'submit' && !existingReadiness ? buildReadinessPayload(readinessForm, unit) : null;
    if (built && !built.payload) {
      setReadinessError(built.error || 'Check your readiness values.');
      return;
    }
    await gate.choose(intent, built?.payload ? async () => {
      setReadinessSubmitting(true);
      setReadinessError(null);
      const response = await fetchJson(`${API_BASE}/workouts/mobile/${intent.workoutId}/readiness`, {
        method: 'POST', auth: true, body: built.payload,
      });
      if (!response.ok || !response.json?.ok || !response.json?.readiness_survey?.id) {
        throw new Error(response.json?.error || 'Could not save your check-in. Try again.');
      }
      if (!gate.isCurrent(intent) || intent.scope !== executionScopeRef.current) return;
      const saved = response.json.readiness_survey as SessionReadinessObservation;
      setExistingReadiness(saved);
      setData(current => current?.workout.id === intent.workoutId ? { ...current, readiness_survey: saved } : current);
    } : null, async () => {
      if (intent.scope !== executionScopeRef.current) return;
      setReadinessSubmitting(true);
      setReadinessVisible(false);
      setReadinessChecking(false);
      // Skip sends no readiness request, including no legacy skipped sentinel.
      await beginWorkout();
    }).catch((error: any) => {
      if (gate.isCurrent(intent) && intent.scope === executionScopeRef.current) {
        setReadinessError(error?.message || 'Could not save your check-in. Try again.');
      }
    }).finally(() => {
      if (intent.scope === executionScopeRef.current) setReadinessSubmitting(false);
    });
  };

  // --- Accessory hot-swap (self-coached only) ---
  const [swapAccVisible, setSwapAccVisible] = useState(false);
  const [swapPickerVisible, setSwapPickerVisible] = useState(false);
  const [swapAccItem, setSwapAccItem] = useState<WorkoutItem | null>(null);
  const [swapAccIdentity, setSwapAccIdentity] = useState<GeneralMovementIdentity | null>(null);
  const [swapError, setSwapError] = useState<string | null>(null);
  const hotSwapGateRef = useRef(createHotSwapSubmissionGate());
  const [movementHistoryItem, setMovementHistoryItem] = useState<WorkoutItem | null>(null);
  const [identityPickerItem, setIdentityPickerItem] = useState<WorkoutItem | null>(null);
  const [identityPickerQuery, setIdentityPickerQuery] = useState('');
  const [identityPickerRows, setIdentityPickerRows] = useState<GeneralMovementIdentity[]>([]);
  const [identityPickerLoading, setIdentityPickerLoading] = useState(false);
  const [identityPickerError, setIdentityPickerError] = useState<string | null>(null);
  const [identityPickerContinuation, setIdentityPickerContinuation] =
    useState<EquipmentSelectionContinuation>({ kind: 'none' });
  const [identityPickerManufacturer, setIdentityPickerManufacturer] =
    useState<GeneralMovementIdentity | null>(null);
  const identityPickerRequestRef = useRef(0);
  const [identityPickerSubject, setIdentityPickerSubject] = useState<EquipmentFlowSubject | null>(null);
  const identityPickerVisibleRows = identityPickerRows.filter((row) => {
    const needle = identityPickerQuery.trim().toLowerCase();
    return !needle
      || manufacturerMatchesSearch(needle, row.manufacturer)
      || [row.manufacturer?.display_name, row.display_name, identityPickerSubject?.displayName]
        .filter(Boolean).join(' ').toLowerCase().includes(needle);
  });
  const recentEquipment = identityPickerSubject && !identityPickerManufacturer && !identityPickerQuery.trim()
    ? mostRecentEquipmentChoice(identityPickerRows, identityPickerSubject.allowedTypes)
    : null;
  const identityPickerEntryRef = useRef<{ subject: EquipmentFlowSubject; scope: string } | null>(null);
  const identityPickerSaveRef = useRef<object | null>(null);
  const unknownEquipmentSaveRef = useRef(false);
  const [askForEquipmentDetails, setAskForEquipmentDetails] = useState(true);
  useFocusEffect(useCallback(() => {
    let current = true;
    void fetchJson(`${API_BASE}/mobile/settings`, { method: 'GET', auth: true }).then((response) => {
      if (current && response.ok && response.json?.ok) {
        setAskForEquipmentDetails(response.json.ask_for_equipment_details !== false);
      }
    }).catch(() => {});
    return () => { current = false; };
  }, [executionScope]));
  const [swapAccForm, setSwapAccForm] = useState({
    sets: '',
    rir: '',
  });
  const [swapRepTarget, setSwapRepTarget] = useState<AccessoryRepTarget>({ mode: 'FIXED', fixed: '10' });

  useEffect(() => {
    const itemId = Number(swapAccItem?.id || 0);
    if (!itemId || !acceptedSetEvidenceItemIds.has(itemId)) return;
    setSwapPickerVisible(false);
    setSwapAccVisible(false);
    setSwapAccItem(null);
    setSwapAccIdentity(null);
  }, [
    acceptedSetEvidenceItemIds,
    swapAccItem?.id,
  ]);

  const sessionMovementHistoryResolution = (item: WorkoutItem, athleteId: number) =>
    resolveMovementHistoryLaunchForItem({
      athleteId,
      item,
      includeEquipmentContext: askForEquipmentDetails
        && !isUnspecifiedEquipmentIdentity(activeEquipmentIdentity(item)),
    });

  const openCanonicalMovementHistory = (item: WorkoutItem) => {
    const resolution = sessionMovementHistoryResolution(item, Number(data?.workout?.athlete_id || 0));
    if (!resolution.ok) {
      if (__DEV__) console.warn('[MovementHistory] launch rejected', resolution.reason, item.id);
      Alert.alert('History unavailable', resolution.message);
      return;
    }
    router.push(movementHistorySheetRoute(resolution.target, { kind: 'session_logger', workoutId: Number(workoutId), athleteId: resolution.target.athleteId, mode: coachPreviewRequested ? 'preview' : 'execute', displayUnit: unit }) as never);
  };

  const openSwapAcc = (it: WorkoutItem) => {
    const currentWorkout = data?.workout;
    const authority = resolveSubstitutionAuthority({
      serverAuthority: data?.permissions?.substitution_authority,
      canHotSwap: data?.permissions?.can_hot_swap,
      permissionIsSelfCoached: data?.permissions?.is_self_coached,
      accountIsSelfCoached: user?.is_self_coached,
      isCoachPreview: coachPreviewRequested,
    });
    const swapAction = accessorySwapActionForItem({
      substitutionAuthority: authority,
      hasApprovedSubstitutions: approvedSubstitutionIdentities(it.approved_sub_identities).length > 0,
      isCoachPreview:
        coachPreviewRequested
        && data?.view_mode === 'coach_preview'
        && data?.permissions?.view_only === true,
      sessionLifecycle: deriveScreenMode(currentWorkout?.status),
      targetItemHasSetLogs: itemHasPersistedSetLogs(it),
      targetItemHasRemainingSets: nextMissingSetIndex(
        it.set_logs,
        positiveInt(accessoryExecutionItem(it).sets),
      ) != null,
      acceptedPersistedSetLogForItem: acceptedSetEvidenceItemIds.has(Number(it.id)),
    });
    if (!swapAction) return;
    education.markLearned('active-session-edit');
    setSwapError(null);
    setSwapAccItem(it);
    // The programmed/effective identity is context, never a selectable
    // replacement. A deliberate new governed identity is required.
    setSwapAccIdentity(null);
    setSwapAccForm({
      sets: (it.performed_sets ?? it.sets) != null ? String(it.performed_sets ?? it.sets) : '',
      rir: (it.performed_rir_target ?? it.rir_target) != null ? String(it.performed_rir_target ?? it.rir_target) : '',
    });
    setSwapRepTarget(accessoryRepTargetFromText(
      it.performed_reps_text || it.reps_text || (it.reps != null ? String(it.reps) : '10'),
    ));
    setSwapPickerVisible(true);
  };

  const resetSwapPrescription = () => {
    if (!swapAccItem) return;
    setSwapAccForm({
      sets: (swapAccItem.performed_sets ?? swapAccItem.sets) != null ? String(swapAccItem.performed_sets ?? swapAccItem.sets) : '',
      rir: (swapAccItem.performed_rir_target ?? swapAccItem.rir_target) != null ? String(swapAccItem.performed_rir_target ?? swapAccItem.rir_target) : '',
    });
    setSwapRepTarget(accessoryRepTargetFromText(
      swapAccItem.performed_reps_text || swapAccItem.reps_text || (swapAccItem.reps != null ? String(swapAccItem.reps) : '10'),
    ));
  };

  const swapPreviousPrescription = swapAccItem ? accessoryTargetLine(swapAccItem) : '';
  const swapReplacementPrescription = swapAccItem
    ? `${positiveInt(Number(swapAccForm.sets || 0))}×${accessoryRepTargetText(swapRepTarget) || '—'}${swapAccForm.rir === '' ? '' : ` @${swapAccForm.rir} RIR`}`
    : '';

  const saveSwapAcc = async () => {
    if (!workoutId || !swapAccItem || hotSwapGateRef.current.isWorking()) return;
    if (
      itemHasPersistedSetLogs(swapAccItem)
      || acceptedSetEvidenceItemIds.has(Number(swapAccItem.id))
    ) {
      setSwapPickerVisible(false);
      setSwapAccVisible(false);
      setSwapAccItem(null);
      setSwapAccIdentity(null);
      setError('This movement has saved Sets and can no longer be swapped.');
      return;
    }

    const setsStr = String(swapAccForm.sets || '').trim();
    const repsText = accessoryRepTargetText(swapRepTarget);
    const rirStr = String(swapAccForm.rir || '').trim();

    if (!swapAccIdentity?.id) {
      setSwapError('Select a movement.');
      return;
    }

    let sets: number | null = null;
    if (setsStr !== '') {
      const n = parseInt(setsStr.replace(/[^0-9]/g, ''), 10);
      if (!Number.isFinite(n) || n < 0) {
        setSwapError('Enter a valid number of Sets.');
        return;
      }
      sets = n;
    }

    let rir: number | null = null;
    if (rirStr !== '') {
      const cleaned = rirStr.replace(/[^0-9.\-]/g, '').replace(/(?!^)-/g, '');
      const n = parseFloat(cleaned);
      if (!Number.isFinite(n)) {
        setSwapError('Enter a valid RIR.');
        return;
      }
      rir = n;
    }

    const sameMovement = Number(swapAccItem.movement_definition_id) === Number(swapAccIdentity.id);
    const unchangedPrescription = substitutionAuthority !== 'self_governed' || (
      sets === (swapAccItem.performed_sets ?? swapAccItem.sets ?? null)
      && rir === (swapAccItem.performed_rir_target ?? swapAccItem.rir_target ?? null)
      && repsText === accessoryRepTargetText(accessoryRepTargetFromText(
        swapAccItem.performed_reps_text || swapAccItem.reps_text || (swapAccItem.reps != null ? String(swapAccItem.reps) : '10'),
      ))
    );
    if (sameMovement && unchangedPrescription) {
      // A same-ID selection has no write to reconcile, including on the old
      // TestFlight API whose Swap endpoint would reset selected equipment.
      setSwapPickerVisible(false);
      setSwapAccVisible(false);
      setSwapAccItem(null);
      setSwapAccIdentity(null);
      return;
    }

    const swapOwner = executionScope;
    if (!hotSwapGateRef.current.begin()) return;
    try {
      setSavingItemId(swapAccItem.id);
      setSwapError(null);
      // An older background read must not replace the authoritative mutation.
      workoutRequestManagerRef.current.cancel();
      const result = await executeActiveSessionHotSwap({
        sessionId: Number(workoutId),
        itemId: Number(swapAccItem.id),
        openedMovementId: Number(swapAccItem.movement_definition_id),
        replacementId: Number(swapAccIdentity.id),
        replacementName: swapAccIdentity.display_name || '',
        prescription: substitutionAuthority === 'self_governed'
          ? { sets, repsText, rir } : null,
        request: async (path, options) => fetchJson(`${API_BASE}${path}`, {
          ...options, auth: true,
        }),
        trace: __DEV__ ? (event) => console.info('[Session Hot Swap]', event) : undefined,
      });

      if (executionScopeRef.current !== swapOwner) return;
      let savedItem = result.item as WorkoutItem;
      const authoritativeSession = result.session as WorkoutPayload;
      const priorEquipment = swapAccItem.performed_movement_identity;
      if (!result.alreadyApplied && sameMovement && priorEquipment?.key?.startsWith('machine_equipment_')
        && Number(savedItem?.performed_movement_identity?.id) !== Number(priorEquipment.id)) {
        // Older APIs reset equipment when only the prescription changed.
        // Retain the athlete's explicit selection through their existing
        // equipment endpoint; the current API preserves it in the first write.
        const retained = await fetchJson(`${API_BASE}/workouts/mobile/${workoutId}/items/${swapAccItem.id}/performed-identity`, {
          method: 'PUT', auth: true, body: { movement_definition_id: priorEquipment.id },
        });
        if (!retained.ok || !retained.json?.ok
          || Number(retained.json.performed_movement_identity?.id) !== Number(priorEquipment.id)) {
          hotSwapGateRef.current.end();
          void fetchWorkout({ silent: true, reason: 'manual' });
          throw new Error('Prescription saved, but equipment could not be retained. Choose your equipment again before logging.');
        }
        if (executionScopeRef.current !== swapOwner) return;
        if (savedItem) savedItem = { ...savedItem, performed_movement_identity: retained.json.performed_movement_identity };
      }
      if (savedItem) {
        const projectSavedItem = (payload: WorkoutPayload | null) => payload ? {
          ...payload,
          workout: {
            ...payload.workout,
            accessory_groups: payload.workout.accessory_groups.map((group) => ({
              ...group,
              items: group.items.map((item) => Number(item.id) === Number(savedItem.id)
                ? { ...item, ...savedItem, set_logs: item.set_logs || [] }
                : item),
            })),
          },
        } : payload;
        // Start from the precondition GET, so all other Session rows are as
        // current as the server read used for this mutation.
        dataRef.current = projectSavedItem(authoritativeSession);
        setData(dataRef.current);
      }
      setSwapAccVisible(false);
      setSwapAccItem(null);
      rememberScroll();
      // The accepted response is projected synchronously. Reconciliation is
      // silent and must never launch equipment selection; that gate belongs
      // immediately before the first performed SetLog.
      hotSwapGateRef.current.end();
      void fetchWorkout({ silent: true, reason: 'manual' });
    } catch (err: any) {
      setSwapError(err?.message || 'Could not swap this movement. Try again.');
    } finally {
      hotSwapGateRef.current.end();
      setSavingItemId(null);
    }
  };

  const openEditSet = (
    itemId: number,
    setLog: SetLog,
    opts: { mode: 'rpe' | 'rir'; movementName: string }
  ) => {
    setError(null);
    const rawWeight =
      setLog.actual_weight_kg != null
        ? unit === 'kg'
          ? formatWeight(setLog.actual_weight_kg, 'kg')
          : String(roundToNearestGymIncrementLb(setLog.actual_weight_kg / KG_PER_LB))
        : '';
    const weightOptions = buildEditWeightOptions(opts.mode, unit, rawWeight);
    const repsOptions = ['0', ...Array.from({ length: opts.mode === 'rpe' ? 20 : 30 }, (_, idx) => String(idx + 1))];
    const metricOptions = opts.mode === 'rpe'
      ? Array.from({ length: 11 }, (_, idx) => formatWheelNumber(5 + idx * 0.5))
      : Array.from({ length: 11 }, (_, idx) => formatWheelNumber(idx * 0.5));
    const rawMetric = opts.mode === 'rpe' ? setLog.actual_rpe : setLog.actual_rir;

    setEditSetCtx({
      itemId,
      setIndex: setLog.set_index,
      setLogId: setLog.id,
      evidenceRevision: (() => {
        const item = [...(data?.workout?.core_items || []), ...(data?.workout?.accessory_groups || []).flatMap(group => group.items)]
          .find(candidate => candidate.id === itemId);
        const revision = Number((item as any)?.evidence_revision);
        return Number.isInteger(revision) && revision > 0 ? revision : null;
      })(),
      mode: opts.mode,
      movementName: opts.movementName,
      loggedWeightKg: setLog.actual_weight_kg ?? null,
      loggedReps: setLog.actual_reps ?? null,
      loggedRpe: setLog.actual_rpe ?? null,
      loggedRir: setLog.actual_rir ?? null,
    });

    setEditSetForm({
      weight: nearestWheelValue(weightOptions, rawWeight, weightOptions[0] || '0'),
      reps: nearestWheelValue(repsOptions, setLog.actual_reps != null ? String(setLog.actual_reps) : '', '0'),
      rpe: opts.mode === 'rpe'
        ? nearestWheelValue(metricOptions, rawMetric != null ? formatWheelNumber(Number(rawMetric)) : '', '8')
        : '',
      rir: opts.mode === 'rir'
        ? nearestWheelValue(metricOptions, rawMetric != null ? formatWheelNumber(Number(rawMetric)) : '', '2')
        : '',
    });

    setEditSetVisible(true);
  };

  const saveEditedSet = async () => {
    if (!workoutId || !editSetCtx || editSetInFlightRef.current) return;
    const ownerAtDispatch = executionScope;
    const assertEditOwner = () => {
      if (!screenMountedRef.current || executionScopeRef.current !== ownerAtDispatch) throw new Error('Session ownership changed.');
    };

    let weightInUnit =
      editSetForm.weight.trim() === '' ? NaN : parseFloat(editSetForm.weight);

    const repsStr = String(editSetForm.reps ?? '').replace(/[^0-9]/g, '');
    const reps = repsStr ? Number(repsStr) : NaN;

    // Zero is a performed load (for example, bodyweight with no added load),
    // not missing input. Match the canonical edit-set API's nonnegative rule.
    if (!Number.isFinite(weightInUnit) || weightInUnit < 0) {
      setError('Weight required');
      return;
    }
    if (!Number.isFinite(reps) || reps < 0) {
      setError('Reps required');
      return;
    }

    if (unit === 'lb') {
      weightInUnit = roundToNearestGymIncrementLb(weightInUnit);
    }

    const weightKg = unit === 'kg' ? weightInUnit : weightInUnit * KG_PER_LB;

    let actual_rpe: number | null = null;
    let actual_rir: number | null = null;

    if (editSetCtx.mode === 'rpe') {
      actual_rpe =
        editSetForm.rpe.trim() === '' ? null : parseFloat(editSetForm.rpe);
      if (editSetForm.rpe.trim() !== '' && !Number.isFinite(actual_rpe as number)) {
        setError('Enter a valid RPE');
        return;
      }
    } else {
      actual_rir =
        editSetForm.rir.trim() === '' ? null : parseFloat(editSetForm.rir);
      if (editSetForm.rir.trim() !== '' && !Number.isFinite(actual_rir as number)) {
        setError('Enter a valid RIR');
        return;
      }
    }

    try {
      editSetInFlightRef.current = true;
      assertEditOwner();
      setEditSetSubmitting(true);
      setSavingItemId(editSetCtx.itemId);
      setError(null);

      const isDevFixtureSet = isIdealWorkoutDetailPreview
        && data?.workout?.accessory_groups?.some((group) =>
          group.items.some((item) =>
            item.id === editSetCtx.itemId
            && (item.set_logs || []).some((log) => log.id === editSetCtx.setLogId),
          ),
        );
      if (isDevFixtureSet) {
        setData((current) => current ? {
          ...current,
          workout: {
            ...current.workout,
            accessory_groups: current.workout.accessory_groups.map((group) => ({
              ...group,
              items: group.items.map((item) => item.id !== editSetCtx.itemId
                ? item
                : {
                    ...item,
                    set_logs: (item.set_logs || []).map((log) =>
                      log.id !== editSetCtx.setLogId
                        ? log
                        : {
                            ...log,
                            actual_weight_kg: weightKg,
                            actual_reps: reps,
                            actual_rpe,
                            actual_rir,
                          }),
                  }),
            })),
          },
        } : current);
        feedbackDispatch({ type: 'SET_EDITED', sourceSetLogId: editSetCtx.setLogId });
        setEditSetVisible(false);
        setEditSetCtx(null);
        showSetMutationNotice('Set updated · progress recalculated');
        return;
      }

      const desired = { actual_weight_kg: weightKg, actual_reps: reps, actual_rpe, actual_rir };
      const body = Object.freeze({ ...desired, set_index: editSetCtx.setIndex, set_log_id: editSetCtx.setLogId,
        ...(editSetCtx.evidenceRevision != null ? { expected_evidence_revision: editSetCtx.evidenceRevision } : {}),
      });
      const json = await recoverSetEdit({
        workoutId: String(workoutId), itemId: editSetCtx.itemId, setLogId: editSetCtx.setLogId,
        desired, expectedRevision: editSetCtx.evidenceRevision, assertOwner: assertEditOwner,
        request: () => fetchJson(`${API_BASE}/workouts/mobile/${workoutId}/items/${editSetCtx.itemId}/edit_set`, {
          method: 'POST',
          auth: true,
          body,
        }),
      });
      assertEditOwner();

      feedbackDispatch({ type: 'SET_EDITED', sourceSetLogId: editSetCtx.setLogId });
      const invalidatedEventIds = Array.isArray(json?.invalidated_recognition_event_ids)
        ? json.invalidated_recognition_event_ids.map(Number).filter(Number.isFinite)
        : [];
      feedbackDispatch({ type: 'INVALIDATE_EVENTS', eventIds: invalidatedEventIds });
      if (workoutId) void invalidateRecognitionForSet(String(workoutId), editSetCtx.setLogId).catch(() => feedbackAnalytics('recognition_invalidation_storage_failed', { mutation: 'edit', source_set_log_id: editSetCtx.setLogId }));
      if (workoutId) void invalidateRecognitionEvents(String(workoutId), invalidatedEventIds).catch(() => feedbackAnalytics('recognition_invalidation_storage_failed', { mutation: 'edit', count: invalidatedEventIds.length }));
      feedbackAnalytics('recognition_invalidated_before_display', { source_set_log_id: editSetCtx.setLogId, mutation: 'edit' });

      setEditSetVisible(false);
      setData(current => applyConfirmedSetEdit(current, editSetCtx.itemId, editSetCtx.setLogId, json.set, json.item_evidence_revision));
      setEditSetCtx(null);
      rememberScroll();
      showSetMutationNotice('Set updated · progress recalculated');
      void fetchWorkout({ silent: true, reason: 'post_set' });
    } catch (err: any) {
      console.log('saveEditedSet error', err);
      if (screenMountedRef.current && executionScopeRef.current === ownerAtDispatch) {
        setError(isApiRequestError(err) && (err.kind === 'network' || err.kind === 'timeout')
          ? "Couldn't confirm this edit. Your changes are still here. Try again."
          : err?.message || 'Error updating set');
      }
    } finally {
      editSetInFlightRef.current = false;
      if (screenMountedRef.current && executionScopeRef.current === ownerAtDispatch) {
        setEditSetSubmitting(false);
        setSavingItemId(null);
      }
    }
  };

  const deleteSetLog = async (itemId: number, setLogId: number) => {
    if (!workoutId || !setLogId) return;

    try {
      setEditSetSubmitting(true);
      setSavingItemId(itemId);
      setError(null);

      const isDevFixtureSet = isIdealWorkoutDetailPreview
        && data?.workout?.accessory_groups?.some((group) =>
          group.items.some((item) =>
            item.id === itemId
            && (item.set_logs || []).some((log) => log.id === setLogId),
          ),
        );
      if (isDevFixtureSet) {
        setData((current) => current ? {
          ...current,
          workout: {
            ...current.workout,
            accessory_groups: current.workout.accessory_groups.map((group) => ({
              ...group,
              items: group.items.map((item) => item.id !== itemId
                ? item
                : {
                    ...item,
                    set_logs: (item.set_logs || []).filter(
                      (log) => log.id !== setLogId,
                    ),
                  }),
            })),
