      setError('Reps required');
      return;
    }
    if (reps > 0 && rpe == null) {
      setError('Enter a valid top set RPE');
      return;
    }

    // ROUND lbs before conversion
    if (unit === 'lb') {
      weightInUnit = roundToNearestGymIncrementLb(weightInUnit);
    }

