  ref={registerMovementCardRef(`core:${core.id}`)}\n                collapsable={false}\n              >\n                <CoreMovementLedgerRow\n                  state={presentationState}\n                  title={resolveLoggerMovementIdentity(core).displayName}\n                  designation={formatDesignation((core as any).designation) || null}\n                  variantLabel={variantLabel}\n                  scheme={schemeNode}\n                  headerPrescription={headerPrescription}\n                  loggerFocus={\n                    (isPreSession || isActiveSession) && detailsExpanded\n                      ? movementPresentation.loggerFocus\n                      : null\n                  }\n                  expanded={detailsExpanded}\n                  detailRows={detailsExpanded ? movementPresentation.detailRows : undefined}\n                  warmupAction={(\n                    isActiveSession\n                    && (\n                      (!hasAnyLogs && (\n                        core.smart_warmup?.eligible\n                        || core.smart_warmup?.session?.status === 'active'\n                      ))\n                      || core.smart_warmup?.session?.status === 'completed'\n                    )\n                  ) ? (\n                    <Pressable\n                      accessibilityRole=\"button\"\n                      accessibilityLabel={core.smart_warmup?.session?.status === 'active' ? `Resume ${liftDisplayName(core)} warmups` : core.smart_warmup?.session?.status === 'completed' ? `Review ${liftDisplayName(core)} warmup summary` : `Begin ${liftDisplayName(core)} warmups`}\n                      onPress={() => setWarmupItemId(core.id)}\n                      style={styles.smartWarmupEntry}\n                    >\n                      <Ionicons name=\"flame-outline\" size={20} color={SLColors.accentViolet} />\n                      <View style={styles.smartWarmupEntryCopy}>\n                        <Text style={styles.smartWarmupEntryTitle}>{core.smart_warmup?.session?.status === 'active' ? 'Resume Warmups' : core.smart_warmup?.session?.status === 'completed' ? 'Warmup Summary' : 'Begin Warmups'}</Text>\n                        <Text style={styles.smartWarmupEntryDetail}>\n                          {core.smart_warmup?.session\n                            ? formatWarmupPhysicalConfiguration(core.smart_warmup.session.loading_configuration, unit)\n                            : 'Built from today’s prescribed range'}\n                        </Text>\n                      </View>\n                      <Ionicons name=\"chevron-forward\" size={20} color={SLColors.textMuted} />\n                    </Pressable>\n                  ) : null}\n                  meta={coreIsComplete ? coreSummary.meta : `${coreCompletionLoggedCount}/${coreCompletionTotal || totalSets || 0} sets logged`}\n                  top={coreIsComplete ? coreSummary.top : formatLookbackLine(getLookbackBest(core), unit, core)}\n                  movementNote={core.notes}\n                  historyPeek={detailsExpanded ? historyPeekFor(core) : null}\n                  visualContext={movementVisualContextFor(\n                    core,\n                    movementPresentation.renderWeight,\n                  )}\n                  submissionStatus={feedbackState.submission.status}\n                  submissionItemId={feedbackState.submission.activeItemId}\n                  reduceMotion={reduceMotion}\n                  completedSetSwipeTooltipSetLogId={completedSetSwipeTooltipSetLogId}\n                  onCompletedSetSwipeTooltipStarted={handleCompletedSetSwipeTooltipStarted}\n                  onOpportunityDisplayed={(opportunity) => feedbackAnalytics('opportunity_context_displayed', {\n                    type: opportunity.eyebrow,\n                    item_id: movementPresentation.loggerFocus?.itemId || core.id,\n                  })}\n                  onEditPrescription={canEditPrescription\n                    ? () => openPrescription(movementPresentation.loggerFocus?.itemId || core.id) : undefined}\n                  sessionIndex={coreIndex + 1}\n                  sessionLifecycle={screenMode}\n                  onOpen={() => toggleMovementCard(`core:${core.id}`)}\n                />\n              </View>\n            );\n          })}\n        </View>\n\n        {/* Accessories use the same peer movement logger model as core work. */}\n        <View\n          style={[\n            styles.sectionBlock,\n            styles.accessorySectionBlock,\n            styles.canonicalMovementList,\n          ]}\n        >\n          {workout.accessory_groups.map((grp, idx) => {\n            const isSuperset = !!grp.group;\n\n            if (isSuperset && grp.group) {\n              const detailKey = `ss:${grp.group}`;\n              if ((isActiveSession || focusedMovementKey) && focusedMovementKey !== detailKey) return null;\n              const workspaceItems = supersetWorkspaceItems(grp.items);\n              const roundModel = buildSupersetRoundModel(workspaceItems);\n              const memberFocus = supersetWorkspaceFocus(roundModel, supersetMemberSelection);\n              if (focusedMovementKey === detailKey) {\n                const nextItem = grp.items.find(item => item.id === memberFocus.next?.itemId);\n                focusedSetAction = canLog && !isCoachView && nextItem\n                  ? () => openAccessoryWheel(nextItem) : undefined;\n                focusedSetLabel = memberFocus.next\n                  ? `Log ${supersetMemberLabel(grp.group, memberFocus.next.position)} · Set ${memberFocus.next.nextSetIndex}`\n                  : 'Choose next movement';\n              }\n              return (\n                <View\n                  collapsable={false}\n                  key={detailKey}\n                  ref={registerMovementCardRef(detailKey)}\n                >\n                  <SupersetRoundWorkspace\n                    canLog={canLog && !isCoachView}\n                    phase={isPreSession ? 'pre' : isFinishedSession ? 'complete' : 'active'}\n                    expanded={isActiveSession || Boolean(expandedCompletedMovements[detailKey])}\n                    selectedItemId={memberFocus.member?.itemId}\n                    onSelectMember={(itemId) => {\n                      setSupersetMemberSelection({ itemId, evidenceKey: memberFocus.evidenceKey });\n                      openMovementCard(detailKey);\n                    }}\n                    groupLabel={grp.group}\n                    model={roundModel}\n                    onConfigureEquipment={(itemId) => {\n                      const item = grp.items.find(\n                        (candidate) => candidate.id === itemId,\n                      );\n                      if (item) openIdentityPicker(item);\n                    }}\n                    onDeleteSet={(item, log) =>\n                      confirmDeleteSet(item.id, log as SetLog)}\n                    onEditSet={(item, log) =>\n                      openEditSet(item.id, log as SetLog, {\n                        mode: 'rir',\n                        movementName: item.title,\n                      })}\n                    onOpenHistory={(itemId) => {\n                      const item = grp.items.find(\n                        (candidate) => candidate.id === itemId,\n                      );\n                      if (item) openCanonicalMovementHistory(item);\n                    }}\n                    onEditPrescription={canEditPrescription ? openPrescription : undefined}\n                    onSwapMovement={(itemId) => {\n                      const item = grp.items.find(\n                        (candidate) => candidate.id === itemId,\n                      );\n                      if (item) openSwapAcc(item);\n                    }}\n                    reduceMotion={reduceMotion}\n                    swapActionForItem={(itemId) => {\n                      const item = grp.items.find(\n                    